import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './AddHealthRecord.css';

const AddHealthRecord = () => {
  const token = localStorage.getItem("token");
  const [form, setForm] = useState({
    diagnosis: '',
    treatment: '',
    prescription: '',
    patientId: '',
    doctorId: '',
    patientName: ''
  });

  const navigate = useNavigate();

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const recordData = {
      dateCreated: new Date().toISOString(),
      lastUpdated: new Date().toISOString(),
      diagnosis: form.diagnosis,
      treatment: form.treatment,
      prescription: form.prescription,
      isEditable: true,
      patientName: form.patientName,
      patientId: parseInt(form.patientId), // how to get this id's
      doctorId: parseInt(form.doctorId), // how to get this id's 
    };

    try {
      const BASE_URL = process.env.REACT_APP_API_URL;
      console.log(BASE_URL)
      const response = await fetch(`${BASE_URL}/api/MedicalRecord`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify(recordData),
      });

      if (response.ok) {
        navigate('/doctor/healthrecords');
      } else {
        console.error('Failed to add record');
      }
    } catch (error) {
      console.error('Error:', error);
    }
  };

  return (
    <div className="add-record-container">
      <h2>Add New Health Record</h2>
      <form className="add-record-form" onSubmit={handleSubmit}>
      <input name="patientName" type="patientName" placeholder="Patient Name" onChange={handleChange} required />
        <input name="diagnosis" placeholder="Diagnosis" onChange={handleChange} required />
        <input name="treatment" placeholder="Treatment" onChange={handleChange} required />
        <input name="prescription" placeholder="Prescription" onChange={handleChange} required />
        <input name="patientId" type="number" placeholder="Patient ID" onChange={handleChange} required />
        <input name="doctorId" type="number" placeholder="Doctor ID" onChange={handleChange} required />
        <button className="submit-button" type="submit">Submit</button>
      </form>
    </div>
  );
};

export default AddHealthRecord;

